def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp(i):
        return history[i][1]

    def me(i):
        return history[i][0]

    last_opp = opp(n - 1)
    last_me = me(n - 1)

    # Endgame: exploit in the final rounds to secure terminal payoff.
    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    # Count totals
    opp_d_total = 0
    for i in range(n):
        if opp(i) == 'D':
            opp_d_total += 1
    opp_c_total = n - opp_d_total
    opp_rate = opp_d_total / float(n)

    # Recent window
    w = 12 if n >= 12 else n
    recent_d = 0
    for i in range(n - w, n):
        if opp(i) == 'D':
            recent_d += 1

    # Consecutive defections by opponent at the end
    streak = 0
    for i in range(n - 1, -1, -1):
        if opp(i) == 'D':
            streak += 1
        else:
            break

    # If opponent is overwhelmingly cooperative, mostly cooperate with rare probes.
    if opp_rate < 0.1 and recent_d <= 1:
        # Only probe occasionally, and not during a sensitive recovery moment.
        if streak == 0 and last_opp == 'C' and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent just defected.
    if last_opp == 'D':
        # Very high defection: defect without much forgiveness.
        if opp_rate >= 0.6:
            return 'D'
        # Long streak of defection: punish but periodically probe for return.
        if streak >= 4:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if streak >= 2:
            # If we defected too and they still defected, keep punishing.
            if last_me == 'D':
                return 'D'
            return 'D'
        # Single defection: retaliate once.
        if last_me == 'C':
            return 'D'
        # We already retaliated and they defected again -> count as streak case.
        return 'D'

    # Opponent just cooperated.
    if last_me == 'D':
        # We punished; opponent cooperated back: return to cooperation.
        return 'C'

    # Opponent cooperative. Check if they have been mixing in some defections.
    if opp_rate < 0.25:
        # Mostly cooperative: preserve mutual cooperation.
        return 'C'

    if opp_rate < 0.5:
        # Moderately exploitative but currently cooperative:
        # punish occasionally if they were recently defect-heavy, otherwise cooperate.
        if recent_d >= 3:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'

    # Hostile opponent currently cooperating: exploit cautiously.
    if rng.random() < 0.5:
        return 'C'
    return 'D'
